// Package: Azure.Messaging.ServiceBus
using Azure.Messaging.ServiceBus;
using System.Text.Json;

namespace OrderApi.Messaging;

public class OrderQueueSender : IAsyncDisposable
{
    private readonly ServiceBusSender _sender;
    private readonly JsonSerializerOptions _jsonOptions;

    public OrderQueueSender(string connectionString, string queueName)
    {
        var client = new ServiceBusClient(connectionString);
        _sender = client.CreateSender(queueName);
        _jsonOptions = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull
        };
    }

    public async Task SendOrderCreatedAsync(
        OrderCreatedEvent evt,
        CancellationToken cancellationToken = default)
    {
        var json = JsonSerializer.Serialize(evt, _jsonOptions);
        var message = new ServiceBusMessage(new BinaryData(json))
        {
            MessageId = evt.OrderId.ToString(),
            Subject = "OrderCreated",
            ContentType = "application/json",
            ApplicationProperties =
            {
                ["CustomerId"] = evt.CustomerId,
                ["TotalAmount"] = evt.TotalAmount
            }
        };

        // SendAndDeleteTransaction ensures exactly-once if a session is used
        await _sender.SendMessageAsync(message, cancellationToken);
    }

    public async ValueTask DisposeAsync()
    {
        await _sender.DisposeAsync();
    }
}

// --- Event record ---
public record OrderCreatedEvent(
    Guid OrderId,
    Guid CustomerId,
    DateTime CreatedAt,
    decimal TotalAmount,
    List<OrderItem> Items);

public record OrderItem(Guid ProductId, int Quantity, decimal UnitPrice);

// --- Usage in ASP.NET Core ---
// builder.Services.AddSingleton<IOrderQueueSender>(sp =>
//     new OrderQueueSender(connectionString, "orders-queue"));
//
// In a controller:
// await _orderQueueSender.SendOrderCreatedAsync(new OrderCreatedEvent(...));
//
// Expected Service Bus message body (JSON):
// { "orderId": "uuid", "customerId": "uuid", "createdAt": "2026-01-15T...", "totalAmount": 59.99, "items": [...] }

// Package: Azure.Messaging.ServiceBus
using Azure.Messaging.ServiceBus;
using System.Text.Json;

namespace OrderApi.Messaging;

public class OrderProcessor : IHostedService, IAsyncDisposable
{
    private readonly ServiceBusProcessor _processor;
    private readonly IOrderService _orderService;
    private readonly ILogger<OrderProcessor> _logger;
    private readonly JsonSerializerOptions _jsonOptions;

    public OrderProcessor(
        string connectionString,
        string queueName,
        IOrderService orderService,
        ILogger<OrderProcessor> logger)
    {
        _orderService = orderService;
        _logger = logger;
        _jsonOptions = new() { PropertyNameCaseInsensitive = true };

        var client = new ServiceBusClient(connectionString);
        _processor = client.CreateProcessor(queueName, new ServiceBusProcessorOptions
        {
            // Auto-complete is OFF — we settle explicitly
            AutoCompleteMessages = false,
            // Max concurrent calls — tune based on throughput needs
            MaxConcurrentCalls = 4,
            // Prefetch improves throughput by reducing round-trips
            PrefetchCount = 20,
            // Dead-letter after 3 delivery attempts
            MaxAutoLockRenewalDuration = TimeSpan.FromMinutes(5)
        });

        _processor.ProcessMessageAsync += OnMessageReceivedAsync;
        _processor.ProcessErrorAsync += OnErrorAsync;
    }

    private async Task OnMessageReceivedAsync(ProcessMessageEventArgs args)
    {
        try
        {
            var body = args.Message.Body.ToString();
            var evt = JsonSerializer.Deserialize<OrderCreatedEvent>(body, _jsonOptions);

            if (evt is null)
            {
                _logger.LogWarning("Received null event. Dead-lettering.");
                await args.DeadLetterMessageAsync(args.Message, "NullBody", "Message body deserialized to null.");
                return;
            }

            _logger.LogInformation("Processing OrderCreated: {OrderId}", evt.OrderId);
            await _orderService.FulfillOrderAsync(evt, args.CancellationToken);

            // Explicitly complete — removes from the queue
            await args.CompleteMessageAsync(args.Message, args.CancellationToken);
            _logger.LogInformation("Completed: {OrderId}", evt.OrderId);
        }
        catch (JsonException ex)
        {
            _logger.LogError(ex, "Deserialization failed. Dead-lettering message {MessageId}.", args.Message.MessageId);
            await args.DeadLetterMessageAsync(args.Message, "DeserializationError", ex.Message);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Processing failed for {MessageId}. Abandoning.", args.Message.MessageId);
            await args.AbandonMessageAsync(args.Message, cancellationToken: args.CancellationToken);
        }
    }

    private Task OnErrorAsync(ProcessErrorEventArgs args)
    {
        _logger.LogError(args.Exception, "Service Bus error in {EntityPath}: {Reason}",
            args.EntityPath, args.ErrorSource);
        return Task.CompletedTask;
    }

    public Task StartAsync(CancellationToken ct) => _processor.StartProcessingAsync(ct);
    public Task StopAsync(CancellationToken ct) => _processor.StopProcessingAsync(ct);

    public async ValueTask DisposeAsync()
    {
        await _processor.DisposeAsync();
    }
}

// --- Usage ---
// builder.Services.AddHostedService<OrderProcessor>();
// builder.Services.AddSingleton<IOrderService, OrderService>();
//
// Expected log output:
// [Information] Processing OrderCreated: 3fa85f64-5717-4562-b3fc-2c963f66afa6
// [Information] Completed: 3fa85f64-5717-4562-b3fc-2c963f66afa6
